function validate([nums, target]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 1000) return 'nums needs 2 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000)) return 'Each value is an integer between -10^9 and 10^9.';
  if (!Number.isInteger(target) || target < 0 || target > 2000000000) return 'target is an integer between 0 and 2 * 10^9.';
  return null;
}

