function maximumJumps(nums, target) {
  const n = nums.length;
  const dp = new Array(n).fill(-1);
  dp[0] = 0;

  for (let j = 1; j < n; j++) {
    for (let i = 0; i < j; i++) {
      if (dp[i] === -1) {
        continue;
      }
      if (Math.abs(nums[j] - nums[i]) <= target) {
        dp[j] = Math.max(dp[j], dp[i] + 1);
      }
    }
  }
  return dp[n - 1];
}

