function maximumJumps(nums, target) {
  // Follow every possible jump sequence from index 0 and keep the longest one that ends at the last index.
  const last = nums.length - 1;
  const longest = (at) => {
    if (at === last) return 0;
    let best = -1;
    for (let next = at + 1; next <= last; next++) {
      if (nums[next] - nums[at] > target || nums[at] - nums[next] > target) continue;
      const rest = longest(next);
      if (rest >= 0 && rest + 1 > best) best = rest + 1;
    }
    return best;
  };
  return longest(0);
}

