function generate(rand, size) {
  const n = size === 'large' ? 1000 : 2 + Math.floor(rand() * 8);
  const pick = rand();
  const spread = pick < 0.15 ? 1000000000 : pick < 0.3 ? 2 : size === 'large' ? 1 + Math.floor(rand() * 1000000) : 1 + Math.floor(rand() * 10);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * spread + 1)) - spread);
  const choice = rand();
  let target;
  if (choice < 0.1) target = 0;
  else if (choice < 0.2) target = 2000000000;
  else target = Math.min(2000000000, Math.floor(rand() * (spread + 1)));
  return [nums, target];
}
